fn main(){let args=std::env::args().collect::<Vec<_>>();if args.get(2).map(String::as_str)==Some("--settings-only"){let mut o=Output(Vec::new());physics::migration_grind_runtime_load(std::path::Path::new(&args[1]),&mut o);let mut output=std::io::BufWriter::new(std::io::stdout().lock());for w in o.0{output.write_all(&w.to_le_bytes()).unwrap();}return;}let mut data=Vec::new();std::io::stdin().read_to_end(&mut data).unwrap();let mut i=Input{data,at:0};let mut o=Output(Vec::new());physics::migration_grind_runtime_run(std::path::Path::new(&args[1]),std::path::Path::new(&args[2]),&mut i,&mut o).unwrap();assert_eq!(i.at,i.data.len());let mut output=std::io::BufWriter::new(std::io::stdout().lock());for w in o.0{output.write_all(&w.to_le_bytes()).unwrap();}}
